import shipping


def test_fee_at_and_above_free_shipping_threshold():
    for amount_cents in (10000, 10001):
        result = shipping.fee(amount_cents)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

import pytest
import shipping


def test_fee_rejects_non_builtin_int_arguments():
    for amount_cents in (True, 1.0, "1"):
        with pytest.raises(TypeError):
            shipping.fee(amount_cents)

